#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* 与 kickpi_k7_camera.c 里那段逐字一致 */
static uint32_t gam(uint32_t g)
{
  uint32_t v = g * 255u;
  uint32_t r = 0;
  uint32_t bit = 1u << 16;

  while (bit > v) bit >>= 2;
  while (bit != 0)
    {
      if (v >= r + bit) { v -= r + bit; r = (r >> 1) + bit; }
      else              { r >>= 1; }
      bit >>= 2;
    }
  return r;
}

int main(void)
{
  int bad = 0;
  for (uint32_t g = 0; g <= 255; g++)
    {
      uint32_t got  = gam(g);
      uint32_t want = (uint32_t)sqrt((double)g * 255.0);
      if (got != want) { if (bad++ < 8) printf("  g=%3u 得 %3u 期望 %3u\n", g, got, want); }
    }
  printf("不一致 %d / 256\n", bad);
  printf("关键点: 0->%u  44->%u  128->%u  255->%u\n",
         gam(0), gam(44), gam(128), gam(255));
  return bad != 0;
}
