static void rk3576_set_clock_selection(struct rk_priv_data *bsp_priv, bool input,
				       bool enable)
{
	unsigned int val = input ? RK3576_GMAC_CLK_SELET_IO :
				   RK3576_GMAC_CLK_SELET_CRU;
